class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def convertToDLL(root):
    def extractLeaves(node):
        if not node:
            return None, None, None

        if not node.left and not node.right:
            return node, node, None

        left_head, left_tail, node.left = extractLeaves(node.left)
        right_head, right_tail, node.right = extractLeaves(node.right)

        if left_head and right_head:
            left_tail.right = right_head
            right_head.left = left_tail
            return left_head, right_tail, node

        if left_head:
            return left_head, left_tail, node

        if right_head:
            return right_head, right_tail, node

        return None, None, node

    _, _, modified_root = extractLeaves(root)
    return modified_root
